ValidationRule.errorConditionFormula:
AND( 
				ISPICKVAL(SC_SourceofContact__c, 'Customer'), 
				ISBLANK(Account.Name), 
				OR( 
								NOT(ISCHANGED(Status)),
								AND(
												ISCHANGED(Status),
												NOT(
																AND(
																				ISPICKVAL(PRIORVALUE(Status), 'New'),
																				NOT(ISPICKVAL(Status, 'New'))
																			)
												    )
											)
				    )
)
